+
+// RF-005: lista de reposición con el faltante (mínimo − stock), de mayor a menor faltante.
+export function listaDeReposicion(movimientos, minimos) {
+  return articulosAReponer(movimientos, minimos)
+    .map((a) => ({ ...a, faltante: a.minimo - a.stock }))
+    .sort((x, y) => y.faltante - x.faltante);
+}
